import { z } from 'zod';
import rawModel from './model.json';

// Serving side of the estimate-calibration model trained in ml/ (see
// ml/MODEL_CARD.md). model.json is generated by `uv run growthtracker-ml train`;
// don't edit it by hand. Everything here mirrors ml/src/growthtracker_ml/
// features.py and model.py line for line, and tests/estimates-logic.test.ts
// checks the two give the same answers on cases the Python side generated.

export const FEATURES = ['intercept', 'log_size', 'priority_high', 'priority_low', 'log_subtasks', 'has_due_date'] as const;
const NO_GOAL = '__none__';

const modelSchema = z.object({
  name: z.literal('estimate-calibration'),
  features: z.array(z.string()),
  coefficients: z.array(z.number()),
  variances: z.object({ user: z.number().positive(), goal: z.number().positive(), noise: z.number().positive() }),
  historyLimit: z.number().int().positive(),
  minHistory: z.number().int().nonnegative(),
  intervals: z.object({
    coverage: z.number().gt(0).lt(1),
    buckets: z.array(z.object({ minHistory: z.number().int().nonnegative(), low: z.number(), high: z.number() })).min(1),
  }),
  clamps: z.object({
    minEstimate: z.number().positive(),
    maxEstimate: z.number().positive(),
    centreEstimate: z.number().positive(),
    maxSubtasks: z.number().int().nonnegative(),
    maxLogRatio: z.number().positive(),
  }),
  metadata: z.looseObject({ version: z.string() }),
});

export type CalibrationModel = z.infer<typeof modelSchema>;

export function loadModel(raw: unknown): CalibrationModel {
  const model = modelSchema.parse(raw);
  if (model.features.join() !== FEATURES.join() || model.coefficients.length !== FEATURES.length) {
    throw new Error(`Estimate model features [${model.features}] don't match this code's [${FEATURES}]`);
  }
  if (model.intervals.buckets[0].minHistory !== 0) throw new Error('Estimate model intervals must start at 0 tasks');
  return model;
}

// Checked once at startup, so a bad model.json fails the deploy, not a request.
export const MODEL = loadModel(rawModel);

export interface TaskInput {
  estimateMinutes: number;
  priority: 'LOW' | 'MEDIUM' | 'HIGH';
  subtasks: number;
  hasDueDate: boolean;
  goalId: string | null;
}

export interface TimedTask extends TaskInput {
  actualMinutes: number;
}

export interface Prediction {
  logMean: number;
  predictedMinutes: number;
  lowMinutes: number;
  highMinutes: number;
  userOffset: number;
  goalOffset: number;
  historyUsed: number;
  goalHistoryUsed: number;
}

const clamp = (value: number, min: number, max: number) => Math.min(Math.max(value, min), max);
const goalKey = (goalId: string | null) => (goalId ? goalId : NO_GOAL);
const dot = (a: readonly number[], b: readonly number[]) => a.reduce((sum, x, i) => sum + x * b[i], 0);

export function featureVector(model: CalibrationModel, task: TaskInput): number[] {
  const { minEstimate, maxEstimate, centreEstimate, maxSubtasks } = model.clamps;
  const estimate = clamp(task.estimateMinutes, minEstimate, maxEstimate);
  const subtasks = clamp(task.subtasks, 0, maxSubtasks);
  return [
    1,
    Math.log(estimate / centreEstimate),
    task.priority === 'HIGH' ? 1 : 0,
    task.priority === 'LOW' ? 1 : 0,
    Math.log1p(subtasks),
    task.hasDueDate ? 1 : 0,
  ];
}

/** The training target: log(actual / estimate), clamped to [1/5, 5] times the estimate. */
export function logRatio(model: CalibrationModel, estimateMinutes: number, actualMinutes: number): number {
  const limit = model.clamps.maxLogRatio;
  return clamp(Math.log(actualMinutes / estimateMinutes), -limit, limit);
}

/**
 * Closed-form posterior means (BLUPs) of the person's offset and each goal's.
 * `history` is most recent first; only the first `historyLimit` tasks count.
 */
export function personalOffsets(model: CalibrationModel, history: readonly TimedTask[]) {
  const { user: userVariance, goal: goalVariance, noise: noiseVariance } = model.variances;
  const sums = new Map<string, number>();
  const counts = new Map<string, number>();
  for (const task of history.slice(0, model.historyLimit)) {
    const key = goalKey(task.goalId);
    const residual = logRatio(model, task.estimateMinutes, task.actualMinutes) - dot(model.coefficients, featureVector(model, task));
    sums.set(key, (sums.get(key) ?? 0) + residual);
    counts.set(key, (counts.get(key) ?? 0) + 1);
  }

  let precision = 1 / userVariance;
  let weighted = 0;
  for (const [key, n] of counts) {
    const v = goalVariance + noiseVariance / n;
    precision += 1 / v;
    weighted += sums.get(key)! / n / v;
  }
  const user = weighted / precision;

  const goals = new Map<string, number>();
  for (const [key, n] of counts) {
    const v = goalVariance + noiseVariance / n;
    goals.set(key, (goalVariance / v) * (sums.get(key)! / n - user));
  }
  return { user, goals, counts };
}

export function predictDuration(model: CalibrationModel, task: TaskInput, history: readonly TimedTask[]): Prediction {
  const { user, goals, counts } = personalOffsets(model, history);
  const key = goalKey(task.goalId);
  const goal = goals.get(key) ?? 0;
  const logMean = dot(model.coefficients, featureVector(model, task)) + user + goal;
  const historyUsed = Math.min(history.length, model.historyLimit);
  const bucket = intervalFor(model, historyUsed);
  return {
    logMean,
    predictedMinutes: task.estimateMinutes * Math.exp(logMean),
    lowMinutes: task.estimateMinutes * Math.exp(logMean + bucket.low),
    highMinutes: task.estimateMinutes * Math.exp(logMean + bucket.high),
    userOffset: user,
    goalOffset: goal,
    historyUsed,
    goalHistoryUsed: counts.get(key) ?? 0,
  };
}

export function intervalFor(model: CalibrationModel, historyUsed: number) {
  let chosen = model.intervals.buckets[0];
  for (const bucket of model.intervals.buckets) {
    if (historyUsed >= bucket.minHistory) chosen = bucket;
  }
  return chosen;
}

/** Durations as people say them: whole minutes under half an hour, then steps of 5. */
export function roundMinutes(minutes: number): number {
  return minutes < 30 ? Math.max(1, Math.round(minutes)) : Math.round(minutes / 5) * 5;
}
